#include <Arduino.h>
#include <WiFi.h>
#include <HTTPClient.h>
#include <WiFiManager.h>
#include <ArduinoJson.h>

// ============================================================================
// WYMUSZENIE KONFIGURACJI WYŚWIETLACZA LILYGO T-EMBED (ST7789)
// ============================================================================
#define USER_SETUP_LOADED 1
#define ST7789_DRIVER     1
#define TFT_WIDTH         170
#define TFT_HEIGHT        320
#define TFT_MOSI          9
#define TFT_SCLK          10
#define TFT_CS            41
#define TFT_DC            16
#define TFT_RST           -1
#define LOAD_GLCD         1
#define SPI_FREQUENCY     27000000
#include <TFT_eSPI.h>

#define PIN_POWER_ON      15 
#define PIN_LCD_BL        21 

TFT_eSPI tft = TFT_eSPI();

// Przykładowa surowa ramka testowa wM-Bus (wersja niezaszyfrowana)
// W rzeczywistym projekcie ta zmienna będzie nadpisywana danymi odebranymi z CC1101
String rawTelegramHEX = "2E44A2111003451234567810070E2F0000000C13453211000C1400000000"; 

// Struktura na zdekodowane dane z API wmbusmeters
struct MeterData {
    String id = "N/A";
    String serial = "N/A";
    String usage = "N/A";
};

// Funkcja wysyłająca surową ramkę do API wmbusmeters.org
MeterData analyzeTelegramOnline(String hexFrame) {
    MeterData data;
    if (WiFi.status() != WL_CONNECTED) return data;

    HTTPClient http;
    // URL API wmbusmeters do analizy telegramów
    http.begin("https://wmbusmeters.org");
    http.addHeader("Content-Type", "application/x-www-form-urlencoded");

    // Budowanie zapytania POST (parametry: telegram, driver=auto)
    String postData = "telegram=" + hexFrame + "&driver=auto&key=";

    int httpResponseCode = http.POST(postData);

    if (httpResponseCode > 0) {
        String response = http.getString();
        Serial.println("Odpowiedź API:");
        Serial.println(response);

        // Parsowanie odpowiedzi (szukanie kluczowych fraz w tekście z wmbusmeters)
        int idPos = response.indexOf("id:");
        int serialPos = response.indexOf("serial:");
        int totalPos = response.indexOf("total_water_m3:"); // Zależy od typu licznika

        if (idPos != -1) {
            int endLine = response.indexOf("\n", idPos);
            data.id = response.substring(idPos + 3, endLine);
            data.id.trim();
        }
        if (serialPos != -1) {
            int endLine = response.indexOf("\n", serialPos);
            data.serial = response.substring(serialPos + 7, endLine);
            data.serial.trim();
        }
        if (totalPos != -1) {
            int endLine = response.indexOf("\n", totalPos);
            data.usage = response.substring(totalPos + 15, endLine) + " m3";
            data.usage.trim();
        } else {
            // Alternatywny tag dla ogólnego zużycia energii/wody
            int usagePos = response.indexOf("usage:");
            if (usagePos != -1) {
                int endLine = response.indexOf("\n", usagePos);
                data.usage = response.substring(usagePos + 6, endLine);
                data.usage.trim();
            }
        }
    } else {
        Serial.print("Błąd HTTP POST: ");
        Serial.println(httpResponseCode);
    }
    http.end();
    return data;
}

// Funkcja odświeżająca interfejs graficzny na ekranie T-Embed
void updateScreen(String status, MeterData meter) {
    tft.fillScreen(TFT_BLACK);
    tft.drawRect(0, 0, tft.width(), tft.height(), TFT_CYAN);

    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(10, 15);
    tft.print("WMBUS INTERNET DECODER");

    tft.setTextSize(1);
    tft.setTextColor(TFT_YELLOW, TFT_BLACK);
    tft.setCursor(10, 45);
    tft.print("Status: " + status);

    tft.setTextSize(2);
    tft.setTextColor(TFT_GREEN, TFT_BLACK);
    tft.setCursor(10, 75);
    tft.print("ID: " + meter.id);

    tft.setTextColor(TFT_MAGENTA, TFT_BLACK);
    tft.setCursor(10, 105);
    tft.print("SERIAL: " + meter.serial);

    tft.setTextColor(TFT_ORANGE, TFT_BLACK);
    tft.setCursor(10, 135);
    tft.print("ODCZYT: " + meter.usage);
}

void setup() {
    Serial.begin(115200);

    // Inicjalizacja zasilania i ekranu LilyGo T-Embed
    pinMode(PIN_POWER_ON, OUTPUT);
    digitalWrite(PIN_POWER_ON, HIGH);
    delay(200);

    tft.init();
    tft.setRotation(3); 
    tft.fillScreen(TFT_BLACK); 

    pinMode(PIN_LCD_BL, OUTPUT);
    digitalWrite(PIN_LCD_BL, HIGH);
    delay(100);

    // Ekran startowy WiFiManager
    tft.setTextColor(TFT_WHITE, TFT_BLACK);
    tft.setTextSize(2);
    tft.setCursor(10, 30);
    tft.println("Uruchamianie menu Wi-Fi...");
    tft.setTextSize(1);
    tft.setCursor(10, 60);
    tft.println("Polacz sie z siecia: T-Embed-WiFi");
    tft.setCursor(10, 80);
    tft.println("Aby skonfigurowac internet.");

    // Otwarcie menedżera sieci Wi-Fi
    WiFiManager wm;
    // Jeśli ESP32 nie połączy się ze znaną siecią, utworzy punkt: T-Embed-WiFi
    if (!wm.autoConnect("T-Embed-WiFi")) {
        Serial.println("Nie udalo sie polaczyc z Wi-Fi. Restart...");
        delay(3000);
        ESP.restart();
    }

    Serial.println("Połączono z Wi-Fi pomyślnie!");
    MeterData emptyData;
    updateScreen("Polaczono. Oczekiwanie na ramke...", emptyData);
}

void loop() {
    // SYMULACJA ODBIORU RAMKI Z CC1101:
    // W tym miejscu docelowo wpisujesz kod odbierający surowe bajty z CC1101 przez SPI
    // i zamieniasz je na string HEX. My symulujemy odbiór co 15 sekund.

    Serial.println("Wysyłanie ramki testowej do wmbusmeters.org...");
    updateScreen("Dekodowanie przez API...", MeterData());

    // Wywołanie zewnętrznego serwera dekodującego
    MeterData zdekodowanyLicznik = analyzeTelegramOnline(rawTelegramHEX);

    // Wyświetlenie gotowych danych na ekranie
    updateScreen("Dane zaktualizowane!", zdekodowanyLicznik);

    // Odpoczynek przed kolejnym zapytaniem (w realnym kodzie: oczekiwanie na przerwanie z GDO0)
    delay(15000); 
}
